  Badge, Big, Center, ChatIcon, FPS, GOLD, HeartIcon, Mask, MicIcon, NAVY, NAVY2, OnAir, PURPLE, PURPLE2, PlayIcon, RED, SAFE_BOTTOM,
  SAFE_TOP, ShareIcon, Small, Span, Star, Symbol, Tag, TvIcon, WHITE, WhatsIcon, Wordmark, MONT, SOFT, cl, io, k, lin, sp,
} from "./pecas";

// Astral TV (cliente "Antônio plenitude 2", id antonio-plenitude-2) — segundo anúncio para prospectar quem quer usar os
// estúdios, ter programa ou podcast, ou participar de programas com Edu Scarfon, Leão Lobo e Claudete Troiano.
// Voz o locutor (src/voz-v1-ed.wav: a gravação com a pausa depois de "câmera" encurtada em 0,5 s), entra em 0,15 s.
// Jeito: motion (só uma arte e o logo). Base da referência "sites para serviços": tipografia cinética com tarja na
// palavra-chave, peças desenhadas, fundos que se alternam (marinho, roxo, dourado) e o selo da marca embaixo.
// Elemento-fio: a estrela dourada do logo. Abertura diferente do 1º anúncio: "Luz… câmera…" com a placa NO AR.

export const A2_FPS = FPS;
export const A2_DUR = 32.5;
export const A2_FRAMES = Math.round(A2_DUR * FPS);

const Bg: React.FC<{ t: number; c1: string; c2: string }> = ({ t, c1, c2 }) => (
  <AbsoluteFill style={{ background: `radial-gradient(95% 60% at ${50 + Math.sin(t * 0.5) * 10}% ${42 + Math.cos(t * 0.4) * 6}%, ${c2} 0%, ${c1} 72%)` }} />
);
// câmera que nunca para: aproximação lenta da cena inteira
const Cam: React.FC<{ t: number; a: number; b: number; z?: number; children: React.ReactNode }> = ({ t, a, b, z = 0.05, children }) => (
  <AbsoluteFill style={{ transform: `scale(${1 + z * lin(t, a - 0.3, b)})`, transformOrigin: "50% 48%" }}>{children}</AbsoluteFill>
);

// ───────── 1 · Luz… câmera… e agora quem está no ar é você (0–5,45) ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const light = k(t, 0.2, 0.35);
  const vf = io(t, 1.5, 0.45); // cantos do visor fecham na batida de "câmera"
  const m = interpolate(vf, [0, 1], [-60, 0]);
  const corner = (x: number, y: number, sx: number, sy: number) => (
    <div style={{ position: "absolute", left: x + sx * -m, top: y + sy * -m, width: 70, height: 70, opacity: vf, borderLeft: sx > 0 ? `6px solid ${WHITE}` : undefined, borderRight: sx < 0 ? `6px solid ${WHITE}` : undefined, borderTop: sy > 0 ? `6px solid ${WHITE}` : undefined, borderBottom: sy < 0 ? `6px solid ${WHITE}` : undefined }} />
  );
  const fr = Math.floor(t * FPS);
  return (
    <AbsoluteFill>
      <Bg t={t} c1="#060B33" c2={NAVY2} />
      {/* refletor: um cone de luz dourada que acende em "luz" e balança devagar */}
      <AbsoluteFill style={{ opacity: light * 0.9, transform: `rotate(${Math.sin(t * 0.9) * 4}deg)`, transformOrigin: "50% 0%" }}>
        <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(255,214,92,0.42) 0%, rgba(255,214,92,0.08) 70%, rgba(255,214,92,0) 100%)", clipPath: "polygon(44% 0%, 56% 0%, 92% 100%, 8% 100%)", filter: "blur(18px)" }} />
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 540 - 46, top: 150, transform: `scale(${sp(t, 0.1, 0.5)}) rotate(${t * 20}deg)` }}>
        <Star size={92} />
      </div>
      {/* visor de câmera em volta da área segura */}
      {corner(150, 330, 1, 1)}
      {corner(860, 330, -1, 1)}
      {corner(150, 1270, 1, -1)}
      {corner(860, 1270, -1, -1)}
      <div style={{ position: "absolute", left: 186, top: 366, display: "flex", alignItems: "center", gap: 12, opacity: vf, fontFamily: MONT, fontWeight: 700, fontSize: 30, color: WHITE, letterSpacing: "0.06em" }}>
        <div style={{ width: 20, height: 20, borderRadius: "50%", background: RED, opacity: Math.floor(t * 2) % 2 === 0 ? 1 : 0.35 }} />
        REC
      </div>
      <div style={{ position: "absolute", right: 186, top: 368, opacity: vf, fontFamily: MONT, fontWeight: 600, fontSize: 28, color: WHITE, fontVariantNumeric: "tabular-nums", letterSpacing: "0.04em" }}>
        00:00:{String(Math.floor(t)).padStart(2, "0")}:{String(fr % FPS).padStart(2, "0")}
      </div>
      <Cam t={t} a={0} b={5.6} z={0.06}>
        <Center top={SAFE_TOP + 140} bottom={SAFE_BOTTOM - 160}>
          <Span t={t} a={0.22} b={1.5}>
            <Big t={t} at={0.22} size={230} txt="Luz" />
          </Span>
          <Span t={t} a={1.52} b={3.02}>
            <Big t={t} at={1.52} size={170} txt="câmera" />
          </Span>
          <Span t={t} a={3.08} b={9}>
            <Small t={t} at={3.08} txt="e agora quem está" size={56} />
            <div style={{ height: 40 }} />
            <OnAir t={t} at={3.9} w={560} />
            <div style={{ height: 60 }} />
            <Small t={t} at={4.6} txt="é" size={56} />
            <div style={{ height: 14 }} />
            <Tag t={t} at={4.7} size={150} txt="você" />
          </Span>
        </Center>
      </Cam>
    </AbsoluteFill>
  );
};

