        <div style={{ position: "absolute", left: 540 - w / 2, top: 800 - h / 2, width: w, height: h, borderRadius: r, background: mo < 0.5 ? "#050A2A" : GOLD, border: `10px solid ${mo < 0.5 ? "#D9DCF5" : GOLD}`, transform: `scale(${screen})`, boxShadow: "0 40px 80px rgba(0,0,20,0.5)", overflow: "hidden" }}>
          {mo < 0.5 ? (
