              <AbsoluteFill style={{ background: `radial-gradient(80% 70% at 50% 40%, ${PURPLE2} 0%, #050A2A 100%)` }} />
              <div style={{ position: "absolute", left: 26, top: 22, display: "flex", alignItems: "center", gap: 10, fontFamily: MONT, fontWeight: 800, fontSize: 26, color: WHITE, letterSpacing: "0.05em", opacity: k(t, 8.0, 0.3) }}>
                <div style={{ width: 16, height: 16, borderRadius: "50%", background: RED, opacity: Math.floor(t * 2) % 2 === 0 ? 1 : 0.4 }} />
