// ───────── passagens (cada uma diferente) ─────────
type Layer = { a: number; b: number; enter: (t: number) => React.CSSProperties; el: (t: number) => React.ReactNode };
const circleIn = (a: number, x: string, y: string, d = 0.45) => (t: number): React.CSSProperties => ({ clipPath: `circle(${(io(t, a, d) * 150).toFixed(2)}% at ${x} ${y})` });
// estrela de 5 pontas que cresce do ponto (x, y) e vira a cena seguinte
const starIn = (a: number, x: number, y: number) => (t: number): React.CSSProperties => {
  const p = io(t, a, 0.5);
  if (p >= 1) return {};
  const s = 10 + p * 3000;
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const ang = -Math.PI / 2 + (i * Math.PI) / 5 + p * 0.6;
    const rr = (i % 2 === 0 ? 1 : 0.42) * s;
    pts.push(`${(x + Math.cos(ang) * rr).toFixed(1)}px ${(y + Math.sin(ang) * rr).toFixed(1)}px`);
  }
  return { clipPath: `polygon(${pts.join(",")})` };
};
const LAYERS: Layer[] = [
  { a: 0, b: 5.45, enter: () => ({}), el: (t) => <S1 t={t} /> },
  // o roxo sai da tarja "você" e cobre a tela
  { a: 5.45, b: 7.5, enter: circleIn(5.45, "50%", "62%"), el: (t) => <S2 t={t} /> },
  // a cena da TV sobe de baixo
  { a: 7.5, b: 11.25, enter: (t) => ({ transform: `translateY(${((1 - k(t, 7.5, 0.45)) * 1920).toFixed(1)}px)` }), el: (t) => <S3 t={t} /> },
  // faixa dourada varre da esquerda
  { a: 11.25, b: 14.2, enter: (t) => ({ clipPath: `inset(0 ${((1 - io(t, 11.2, 0.42)) * 100).toFixed(2)}% 0 0)` }), el: (t) => <S4 t={t} /> },
  // a estrela do topo cresce e vira a cena seguinte
  { a: 14.2, b: 15.35, enter: starIn(14.15, 540, 555), el: (t) => <S5a t={t} /> },
  // a foto entra da direita
  { a: 15.35, b: 17.85, enter: (t) => ({ transform: `translateX(${((1 - k(t, 15.3, 0.42)) * 1080).toFixed(1)}px)` }), el: (t) => <S5b t={t} /> },
  // corte diagonal
  { a: 17.85, b: 24.9, enter: (t) => { const p = io(t, 17.8, 0.45) * 200; return { clipPath: `polygon(0 0, ${p}% 0, ${p - 100}% 100%, 0 100%)` }; }, el: (t) => <S6 t={t} /> },
  // a TV liga: linha horizontal que abre na vertical
  { a: 24.9, b: 27.2, enter: (t) => { const x = io(t, 24.85, 0.22); const y = io(t, 25.05, 0.3); return { clipPath: `inset(${((1 - y) * 49.6).toFixed(2)}% ${((1 - x) * 50).toFixed(2)}% round 6px)` }; }, el: (t) => <S7a t={t} /> },
  // círculo que abre de baixo para a chamada final
  { a: 27.2, b: 32.6, enter: circleIn(27.15, "50%", "70%", 0.5), el: (t) => <S7b t={t} /> },
];

export const Antonio2: React.FC<{ som?: boolean }> = ({ som = true }) => {
  const t = useCurrentFrame() / FPS;
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {LAYERS.map((L, i) => {
        const next = LAYERS[i + 1];
        const until = next ? next.a + 0.6 : L.b;
        if (t < L.a - 0.06 || t >= until) return null;
        return (
          <AbsoluteFill key={i} style={L.enter(t)}>
            {L.el(t)}
          </AbsoluteFill>
        );
      })}
      {som ? <Audio src={staticFile("antonio2/antonio2-mix.wav")} /> : null}
    </AbsoluteFill>
  );
};

import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { Easing, interpolate } from "remotion";

// Peças do anúncio Astral TV v2 (cliente "Antônio plenitude 2", id antonio-plenitude-2): identidade da arte nova
// (azul-marinho e roxo profundos, dourado nos destaques, logo estrela dourada + "Astral" branco + "TV" dourado).

export const { fontFamily: MONT } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const FPS = 30;
export const NAVY = "#0A1450";
export const NAVY2 = "#16247A";
export const PURPLE = "#2B0B6E";
export const PURPLE2 = "#4A1A9C";
export const GOLD = "#FFC21A";
export const GOLD2 = "#FFDD5C";
export const WHITE = "#FFFFFF";
export const SOFT = "rgba(255,255,255,0.8)";
export const RED = "#FF2D3D";

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
export const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));
// mola curta, com pouco overshoot
export const sp = (t: number, a: number, d = 0.55) => {
  const p = clamp((t - a) / d, 0, 1);
  return p >= 1 ? 1 : 1 - Math.exp(-6 * p) * Math.cos(p * 7.5) * (1 - p * 0.2);
};

// área segura dos Reels: texto em x 170–910 e y 280–1450
export const MAXW = 740;
export const SAFE_TOP = 280;
export const SAFE_BOTTOM = 1450;
const ctx = typeof document !== "undefined" ? document.createElement("canvas").getContext("2d") : null;
export const fit = (txt: string, size: number, maxW = MAXW, weight = 800) => {
  if (!ctx) return size;
  ctx.font = `${weight} ${size}px "${MONT}"`;
  const wd = ctx.measureText(txt.toUpperCase()).width - 0.01 * size * txt.length;
  return wd > maxW ? Math.floor((size * maxW) / wd) : size;
};

// texto que nasce de baixo por máscara e fica parado
export const Mask: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties; d?: number }> = ({ t, at, children, style, d = 0.45 }) => {
  const p = k(t, at, d);
  return (
    <div style={{ overflow: "hidden", paddingBottom: "0.1em", marginBottom: "-0.1em" }}>
      <div style={{ transform: `translateY(${((1 - p) * 115).toFixed(2)}%)`, whiteSpace: "nowrap", ...style }}>{children}</div>
    </div>
  );
};
export const BIG: React.CSSProperties = { fontFamily: MONT, fontWeight: 900, textTransform: "uppercase", letterSpacing: "-0.01em", lineHeight: 1.0, color: WHITE };
export const SMALL: React.CSSProperties = { fontFamily: MONT, fontWeight: 600, letterSpacing: "0.005em", color: SOFT };

export const Big: React.FC<{ t: number; at: number; size: number; txt: string; color?: string; maxW?: number }> = ({ t, at, size, txt, color = WHITE, maxW = MAXW }) => (
  <Mask t={t} at={at} style={{ ...BIG, color, fontSize: fit(txt, size, maxW, 900) }}>{txt}</Mask>
);
export const Small: React.FC<{ t: number; at: number; size?: number; txt: string; color?: string }> = ({ t, at, size = 54, txt, color = SOFT }) => (
  <Mask t={t} at={at} style={{ ...SMALL, color, fontSize: size }}>{txt}</Mask>
);
// tarja dourada inclinada (a da arte): abre do centro e o texto sobe dentro dela
export const Tag: React.FC<{ t: number; at: number; size: number; txt: string; bg?: string; fg?: string }> = ({ t, at, size: want, txt, bg = GOLD, fg = NAVY }) => {
  const size = fit(txt, want, MAXW - want * 0.7, 900);
  return (
    <div style={{ position: "relative", padding: `${size * 0.16}px ${size * 0.34}px ${size * 0.1}px`, transform: "rotate(-2deg)" }}>
      <div style={{ position: "absolute", inset: 0, background: bg, borderRadius: size * 0.16, transform: `scaleX(${k(t, at, 0.32).toFixed(4)})`, boxShadow: "0 14px 30px rgba(0,0,0,0.25)" }} />
      <div style={{ position: "relative" }}>
        <Mask t={t} at={at + 0.08} style={{ ...BIG, color: fg, fontSize: size }}>{txt}</Mask>
      </div>
    </div>
  );
};

