const star5 = (r: number, ri: number) => {
  const p: string[] = [];
  for (let i = 0; i < 10; i++) {
    const ang = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 === 0 ? r : ri;
    p.push(`${(Math.cos(ang) * rr).toFixed(3)},${(Math.sin(ang) * rr).toFixed(3)}`);
  }
  return `M${p.join(" L")} Z`;
};
